          <div class="packing">
            <h4 style="margin-top:0">What to bring</h4>
            <p class="muted">Customize suggestions (toggle items you own or want to bring).</p>
            <div style="display:flex;flex-direction:column;gap:6px;margin-top:8px">
              <label><input type="checkbox" data-item="mat"> Yoga mat or cushion</label>
              <label><input type="checkbox" data-item="blanket"> Blanket</label>
              <label><input type="checkbox" data-item="mask"> Eye mask</label>
              <label><input type="checkbox" data-item="water"> Water bottle</label>
