            <h4 style="margin-top:0">Your selection</h4>
            <div class="muted" style="margin-top:6px">Event: <span id="sel-event">Mar 5, 2026 — Evening Clearing</span></div>
            <div class="muted" style="margin-top:6px">Seats: <span id="sel-seats">1</span></div>
