  <script>
    // Fake availability per event
    const availability = { '2026-03-05':12, '2026-03-12':8, '2026-03-20':6 };
    const eventSel = document.getElementById('event');
    const availEl = document.getElementById('avail');
    const seatCountEl = document.getElementById('seat-count');
    const inc = document.getElementById('inc');
    const dec = document.getElementById('dec');
    const selSeats = document.getElementById('sel-seats');
    const selEventDisplay = document.getElementById('sel-event');
    const selEventNameMap = { '2026-03-05':'Mar 5, 2026 — Evening Clearing (6:30pm)', '2026-03-12':'Mar 12, 2026 — Midday Pause (12:00pm)', '2026-03-20':'Mar 20, 2026 — New Cycle Mini (8:00am)' };

    let seats = 1;
    function refresh(){
      const e = eventSel.value; availEl.textContent = availability[e]; if(seats>availability[e]) seats = availability[e]; seatCountEl.textContent = seats; selSeats.textContent = seats; selEventDisplay.textContent = selEventNameMap[e];
    }
    eventSel.addEventListener('change', refresh);
    inc.addEventListener('click', ()=>{ const a = availability[eventSel.value]; if(seats < a) seats++; refresh(); });
    dec.addEventListener('click', ()=>{ if(seats>1) seats--; refresh(); });

    // Packing list generator
    const generateBtn = document.getElementById('generate-list');
    const suggestBtn = document.getElementById('suggest');
    const packOutput = document.getElementById('pack-output');

    function readChecked(){
      return Array.from(document.querySelectorAll('input[type="checkbox"]')).filter(i=>i.checked).map(i=>i.getAttribute('data-item'));
    }

    generateBtn.addEventListener('click', ()=>{
      const chosen = readChecked();
      if(chosen.length===0){ packOutput.innerHTML = '<div>No items selected. Consider a blanket and water.</div>'; return; }
      const labelMap = { mat:'Mat / cushion', blanket:'Blanket', mask:'Eye mask', water:'Water bottle', earplugs:'Soft earplugs', journal:'Journal & pen' };
      packOutput.innerHTML = '<ul style="padding-left:18px;margin:0">' + chosen.map(c=>'<li>'+labelMap[c]+'</li>').join('') + '</ul>';
    });

    suggestBtn.addEventListener('click', ()=>{
      // Simple heuristic: morning events -> bring blanket + water; evening -> blanket + eye mask
      const e = eventSel.value; const hour = selEventNameMap[e].includes('6:30') ? 18 : selEventNameMap[e].includes('8:00') ? 8 : 12;
      const suggestions = (hour<12) ? ['mat','blanket','water'] : (hour>=18) ? ['mat','blanket','mask'] : ['mat','water','journal'];
      // update checkboxes
      document.querySelectorAll('input[type="checkbox"]').forEach(cb=>{ cb.checked = suggestions.includes(cb.getAttribute('data-item')); });
      document.getElementById('generate-list').click();
    });

    // Fake booking confirm: local confirmation
    document.getElementById('book-now').addEventListener('click', ()=>{
      const name = document.getElementById('name').value.trim(); const email = document.getElementById('email').value.trim(); if(!name||!email){ alert('Please provide name and email'); return; }
      alert('Reserved '+seats+' seat(s) for '+selEventNameMap[eventSel.value]+'\nAn email confirmation will be sent to '+email+' (simulated).');
    });

    // initialize
    refresh();
  </script>
</body>
